/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 s=f.read_text(); page='?'; lines=s.splitlines(); hits=[]
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search('florida',l,re.I): hits.append((page,' '.join(lines[max(0,i-2):i+3])))
 print(f.name)
 for p,t in hits: print('PAGE',p,t)
PY"

